package com.example.assets_management.security.rbac.audit;
import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.CreationTimestamp; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="security_audit_log") @Getter @Setter @NoArgsConstructor
public class SecurityAuditLog { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="company_id") private UUID companyId; @Column(name="actor_user_id") private UUID actorUserId; @Column(name="target_user_id") private UUID targetUserId; @Column(name="role_id") private UUID roleId; @Column(name="permission_id") private UUID permissionId; @Enumerated(EnumType.STRING) @Column(name="event_type",nullable=false,length=60) private SecurityAuditEventType eventType; @Column(name="old_value",columnDefinition="TEXT") private String oldValue; @Column(name="new_value",columnDefinition="TEXT") private String newValue; @CreationTimestamp @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt; }
